#include "sector_watch_feed.hpp"
#include "concept_public.hpp"
#include "ths_board_public.hpp"
#include <QNetworkReply>
#include <QJsonDocument>
#include <QUrlQuery>
#include <QDateTime>
#include <cmath>
#include <stdexcept>
namespace sectorWatch {
namespace {
QString now(){return QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs);}
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
QJsonValue parse(const QByteArray& bytes){QJsonParseError error;auto doc=QJsonDocument::fromJson("["+bytes+"]",&error);require(error.error==QJsonParseError::NoError&&doc.isArray()&&doc.array().size()==1,"来源不是有效JSON");return doc.array()[0];}
}
Feed::Feed(QObject* parent,QNetworkAccessManager* manager):QObject(parent),transport(manager?manager:&owned){deadline.setSingleShot(true);deadline.setTimerType(Qt::PreciseTimer);connect(&deadline,&QTimer::timeout,this,[this]{fail("板块读取超过8秒总截止；未保存部分集合");});}
Feed::~Feed(){running=false;++generation;deadline.stop();if(reply){reply->disconnect(this);reply->abort();reply->deleteLater();}}
bool Feed::start(const QJsonObject& q){queryKey(q);require(q["provider"]!=thsBoard::provider||q["kind"]=="catalog","同花顺此入口仅支持目录，成分未接入");if(running)return false;input=q;started=now();page=1;total=-1;assembly=std::make_unique<Assembly>(q,started);++generation;running=true;elapsed.start();deadline.start(8000);request(q["provider"]==thsBoard::provider?"ths-catalog":q["provider"]=="eastmoney-public-board"?(q["kind"]=="catalog"?"catalog-html":conceptPublic::enabled(q)?"concept-guest":"east"):q["kind"]=="catalog"?"nodes":"count");return true;}
void Feed::cancel(){if(running)fail("已取消板块读取；旧完整缓存保留");}
void Feed::request(const QString& phase){if(!running)return;if(elapsed.elapsed()>=8000){fail("板块读取超过8秒总截止");return;}QUrl url;QUrlQuery params;auto code=input["code"].toString();if(phase=="ths-catalog")url=thsBoard::directoryUrl(input["taxonomy"].toString());else if(phase=="catalog-html")url=conceptPublic::directoryUrl(input);else if(phase=="concept-guest")url=conceptPublic::guestUrl(input,page);else if(phase=="east"){
 url=QUrl("https://push2.eastmoney.com/api/qt/clist/get");
 // Public source identifier used by the legacy source; not an account token.
 for(auto pair:QList<QPair<QString,QString>>{{"pn",QString::number(page)},{"pz","500"},{"po","1"},{"np","1"},{"ut","bd1d9ddb04089700cf9c27f6f7426281"},{"fltt","2"},{"invt","2"},{"fid","f12"},{"fs",code.isEmpty()?(input["taxonomy"]=="industry"?"m:90+t:2+f:!50":"m:90+t:3+f:!50"):"b:"+code},{"fields","f2,f3,f6,f12,f13,f14,f62"}})params.addQueryItem(pair.first,pair.second);
 }else{QString method=phase=="nodes"?"getHQNodes":phase=="count"||phase=="verify-count"?"getHQNodeStockCount":"getHQNodeData";url=QUrl("https://vip.stock.finance.sina.com.cn/quotes_service/api/json_v2.php/Market_Center."+method);if(phase!="nodes")params.addQueryItem("node",code);if(phase=="data"){params.addQueryItem("page",QString::number(page));params.addQueryItem("num","100");params.addQueryItem("sort","symbol");params.addQueryItem("asc","1");params.addQueryItem("symbol","");params.addQueryItem("_s_r_a","page");}}
 if(phase!="ths-catalog"&&phase!="catalog-html"&&phase!="concept-guest")url.setQuery(params);QNetworkRequest req(url);req.setAttribute(QNetworkRequest::RedirectPolicyAttribute,QNetworkRequest::ManualRedirectPolicy);req.setAttribute(QNetworkRequest::CookieLoadControlAttribute,QNetworkRequest::Manual);req.setAttribute(QNetworkRequest::CookieSaveControlAttribute,QNetworkRequest::Manual);req.setAttribute(QNetworkRequest::AuthenticationReuseAttribute,QNetworkRequest::Manual);req.setRawHeader("Referer",input["provider"]==thsBoard::provider?"https://q.10jqka.com.cn/":input["provider"]=="eastmoney-public-board"?"https://quote.eastmoney.com/":"https://finance.sina.com.cn/");req.setRawHeader("User-Agent",(input["provider"]==thsBoard::provider||input["provider"]=="eastmoney-public-board")?"Mozilla/5.0 WebStock":"NativeMarketReview/sector-watch");if(phase=="concept-guest")req.setAttribute(QNetworkRequest::Http2AllowedAttribute,false);if(input["provider"]==thsBoard::provider){req.setAttribute(QNetworkRequest::CacheLoadControlAttribute,QNetworkRequest::AlwaysNetwork);req.setRawHeader("Cache-Control","no-cache");}req.setTransferTimeout(int(8000-elapsed.elapsed()));auto token=generation;auto* response=transport->get(req);reply=response;auto bytes=std::make_shared<QByteArray>();connect(response,&QIODevice::readyRead,this,[this,response,bytes,token]{if(token!=generation||!running)return;bytes->append(response->readAll());if(bytes->size()>8*1024*1024)fail("来源响应超过8MiB限制");});connect(response,&QNetworkReply::finished,this,[this,response,bytes,token,phase]{if(token!=generation||!running){response->deleteLater();return;}bytes->append(response->readAll());int status=response->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();auto err=response->error();auto errorText=response->errorString();response->disconnect(this);reply=nullptr;response->deleteLater();if(elapsed.elapsed()>=8000){fail("板块读取超过8秒总截止");return;}if(err!=QNetworkReply::NoError||status<200||status>=300){fail(QString("公开板块源读取失败（HTTP %1 / 网络 %2）：%3；旧完整缓存保留").arg(status).arg(int(err)).arg(errorText.left(1500)));return;}if(bytes->size()>8*1024*1024){fail("来源响应超过8MiB限制");return;}try{receive(*bytes,phase);}catch(const std::exception& e){fail(QString::fromUtf8(e.what()));}});
}
void Feed::receive(const QByteArray& bytes,const QString& phase){if(phase=="ths-catalog"){succeed(thsBoard::directory(bytes,input,started,now()));return;}if(phase=="catalog-html"){succeed(conceptPublic::directory(bytes,input,started,now()));return;}auto value=phase=="concept-guest"?QJsonValue(conceptPublic::guestPayload(bytes)):parse(bytes);if(phase=="nodes"){succeed(sinaCatalog(value,input["taxonomy"].toString(),started,now()));return;}if(phase=="count"||phase=="verify-count"){bool ok=false;double n=value.isDouble()?value.toDouble():value.toString().toDouble(&ok);if(value.isDouble())ok=true;require(ok&&n>0&&n<=10000&&std::floor(n)==n,"新浪成分总数无效");if(phase=="verify-count"){require(total==int(n),"成分总数在本轮发生变化；未存完整缓存");succeed(assembly->finish(now(),elapsed.elapsed()));}else{total=int(n);request("data");}return;}bool done;if(phase=="east"||phase=="concept-guest"){require(value.isObject(),"东方财富页格式错误");done=assembly->appendEastmoney(value.toObject(),page,elapsed.elapsed());}else{require(value.isArray(),"新浪成分页格式错误");done=assembly->appendSina(value.toArray(),total,page,elapsed.elapsed());}if(done){if(phase=="data")request("verify-count");else {auto completed=assembly->finish(now(),elapsed.elapsed());if(phase=="concept-guest"){completed["sourceUrl"]=conceptPublic::guestUrl(input,1,false).toString();completed["sourceTransport"]="official-public-guest-jsonp";completed["sourceRequests"]=page;completed["wirePageSize"]=20;}succeed(completed);}}else{++page;request(phase);}}
void Feed::fail(const QString& message){if(!running)return;running=false;++generation;deadline.stop();if(reply){auto response=reply.data();reply=nullptr;response->disconnect(this);response->abort();response->deleteLater();}QJsonObject partial;try{if(assembly)partial=assembly->finish(now(),elapsed.elapsed(),message);}catch(...){}emit finished(input,partial,message);}
void Feed::succeed(const QJsonObject& s){validate(s);require(s["coverageComplete"].toBool(),"集合不完整");if(elapsed.elapsed()>=8000){fail("板块读取超过8秒总截止");return;}running=false;++generation;deadline.stop();emit finished(input,s,{});}
}
